import{z as B,x as s,o as e,c as p,q as l,j as o,D as E,d as n,s as r,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"HANK","description":"","frontmatter":{"title":"HANK","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hank.md","filePath":"econ/hank.md","lastUpdated":1791063341000}'),d={name:"econ/hank.md"};function C(m,a,K,N,h,D){const t=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=l('<h1 id="hank" tabindex="-1">HANK <a class="header-anchor" href="#hank" aria-label="Permalink to &quot;HANK&quot;">​</a></h1><div class="epigraph"><p>异质、不完全市场与名义刚性接在一起时，货币与财政的传导不再只走欧拉的跨期替代，还走收入与流动性。</p><footer>—— Kaplan, Moll and Violante, Monetary Policy According to HANK, AER 2018</footer></div><p><a href="/econ/wealth-distribution-pareto">上一课</a>把厚尾与资本供给钉在实物不完全市场上。NK 的代表性 RANK 用欧拉把利率接到总需求。本课缺口是 <strong>HANK</strong>：同一套名义刚性，换上异质家庭与流动性资产结构。不重写 Calvo 推导，不重写帕累托机制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RANK：利率升 ⇒ 跨期替代 ⇒ 消费降，收入循环是次要的。Kaplan–Moll–Violante：大量家庭是贫流动性（富于非流动性资本、却缺流动性资产），MPC 高，消费跟的是现金流与工资，不是 \\(\\sigma(i-\\pi^e-\\rho)\\)。货币紧缩经一般均衡压劳动收入，再经高 MPC 放大——间接效应可主导直接欧拉效应。缺口是把 Aiyagari 分布与 NK 价格/工资粘性焊成同一均衡，而不是再估一个 SW。</p><p><span class="marginnote">术语翻译：MPC（边际消费倾向）是「每多拿到 1 元，花掉几毛」。数据显示它差异极大：靠工资过活的家庭 MPC 接近 1，拿资产收益的富人可能只有几分钱。HANK 的关键正在于此：政策的钱先落到谁头上，MPC 决定它是被放大还是被衰减。</span></p><p><span class="marginnote">Kaplan, Moll and Violante, <em>AER</em> 108(3), 2018, 697–743。Werning 对 RANK/HANK 的解析对照。Auclert 的充分统计（再分配渠道）。Gornemann–Kuester–Nakajima 更早的异质 NK。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>家庭：至少两种资产（流动性 vs 非流动性）或偶尔绑定的约束，劳动收入来自企业劳动需求。企业：Calvo 或 Rotemberg 定价。政策：泰勒规则。求解：稳态用 Aiyagari 装置；总量冲击用序列空间线性化或 KS 式定律。IRF 分解：直接（利率进欧拉、进抵押）vs 间接（工资、红利、税收、转移）。校准靶同时含微观 MPC 与宏观脉冲。</p><p><span class="marginnote">数字实例：同样是 1 元转移：给 MPC 0.9 的家庭，当期就花掉 0.9 元；给 MPC 0.05 的家庭，只花 0.05 元。把 100 亿给前者，首轮需求是 90 亿；给后者只有 5 亿——财政账面相同，总需求效果差 18 倍，这就是「传导要看分布」的算术。</span></p>',10)),(e(),o(i,null,{default:E(()=>[r(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E5%88%A9%E7%8E%87%22%5D%20--%3E%20DIR%5B%22%E7%9B%B4%E6%8E%A5%3A%20%E6%AC%A7%E6%8B%89%20%2F%20%E6%8A%B5%E6%8A%BC%22%5D%0A%20%20I%20--%3E%20GE%5B%22GE%3A%20%E5%B7%A5%E8%B5%84%E4%B8%8E%E5%88%A9%E6%B6%A6%22%5D%0A%20%20GE%20--%3E%20INC%5B%22%E9%AB%98%20MPC%20%E5%AE%B6%E5%BA%AD%E7%9A%84%E6%94%B6%E5%85%A5%22%5D%0A%20%20DIR%20--%3E%20C%5B%22%E5%8A%A0%E6%80%BB%20C%22%5D%0A%20%20INC%20--%3E%20C%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("p",null,"与 Smets–Wouters：SW 用习惯、规则拇指冲击模仿「消费跟收入」；HANK 把同一现象写成约束与分布。估计仍难，本课不把 HANK 贝叶斯当默认。",-1)),a[4]||(a[4]=A("h2",{id:"机制",tabindex:"-1"},[n("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=A("p",null,"机制是加总 MPC 与收入循环。谁付利息、谁收红利、谁的工资动，决定再分配：Auclert 的渠道（未预期通胀对名义财富、利率对滚动债务）。若利润归富人、工资归高 MPC 劳动者，紧缩的间接效应更强。流动性资产供给（政府债、准备金）改变贫流动性份额，从而改变乘数——财政课下一课再放大这条。",-1)),(e(),o(i,null,{default:E(()=>[r(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20HIKE%5B%22%E6%94%BF%E7%AD%96%E5%88%A9%E7%8E%87%E4%B8%8A%E8%B0%83%22%5D%20--%3E%20PAYER%5B%22%E6%B5%AE%E5%8A%A8%E5%88%A9%E7%8E%87%E5%80%9F%E5%80%BA%E6%88%B7%EF%BC%9A%E5%88%A9%E6%81%AF%E6%94%AF%E5%87%BA%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20HIKE%20--%3E%20SAVER%5B%22%E5%AD%98%E6%AC%BE%E4%B8%8E%E5%80%BA%E5%88%B8%E6%8C%81%E6%9C%89%E4%BA%BA%EF%BC%9A%E5%88%A9%E6%81%AF%E6%94%B6%E5%85%A5%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20HIKE%20--%3E%20WAGE%5B%22%E6%80%BB%E9%9C%80%E6%B1%82%E8%B5%B0%E5%BC%B1%EF%BC%8C%E5%B7%A5%E8%B5%84%E4%B8%8E%E5%B7%A5%E6%97%B6%E4%B8%8B%E9%99%8D%22%5D%0A%20%20PAYER%20--%3E%20REDIST%5B%22%E6%94%B6%E5%85%A5%E5%86%8D%E5%88%86%E9%85%8D%EF%BC%9A%E9%AB%98%20MPC%20%E5%AE%B6%E5%BA%AD%E7%9A%84%E6%94%B6%E5%85%A5%E8%A2%AB%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20WAGE%20--%3E%20REDIST%0A%20%20SAVER%20--%3E%20REDIST%0A%20%20REDIST%20--%3E%20DEEP%5B%22%E9%AB%98%20MPC%20%E7%BE%A4%E4%BD%93%E5%89%8A%E5%87%8F%E6%B6%88%E8%B4%B9%EF%BC%9A%E9%97%B4%E6%8E%A5%E6%95%88%E5%BA%94%E6%94%BE%E5%A4%A7%E7%B4%A7%E7%BC%A9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>RANK 不是 HANK 的 \\(\\sigma\\to\\infty\\) 极限这么简单：市场结构与谁持有债都要声明。</p><p><span class="marginnote">常见误区：以为 HANK 只是「RANK 加穷人」的加细版。市场结构本身改答案：同样降息，若利息收入集中在高 MPC 家庭（如大量持有浮动收益资产者），直接收入效应可以部分抵消欧拉效应。装置（几资产、谁能借）不是装饰，是结论的一部分。</span></p><p><span class="marginnote">两资产是 KMV 的关键：一资产 HANK 往往让利率的直接收入效应（储蓄者变富）抵消太多。装置选择会改故事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计最优 Taylor 系数。不把限价簿当流动性定义。企业异质与投资下一课序末才接。开放经济 HANK 不在此展开。诊断性预期与疏忽是预期单元，可叠加，不是本课。</p><p>后课默认：HANK = 不完全市场分布 + 名义刚性；传导以间接收入为主是可校准的结果，不是恒等式。下一课：把 MPC 的截面写成可测对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HANK 把异质家庭接到 NK 刚性上。</li><li>货币传导可被间接收入效应主导。</li><li>资产流动性结构决定谁是高 MPC。</li><li>出处：Kaplan, Moll and Violante, <em>AER</em> 2018。</li></ul>',8))])}const u=B(d,[["render",C]]);export{c as __pageData,u as default};
